class Solution {
    public String reorderSpaces(String text){
        int spaces=0;
        for(char value:text.toCharArray())if(value==' ')spaces++;
        String trimmed=text.trim();
        String[] words=trimmed.isEmpty()?new String[0]:trimmed.split(" +");
        int gap=words.length<=1?0:spaces/(words.length-1),tail=spaces-gap*Math.max(0,words.length-1);
        String separator=" ".repeat(gap);
        return String.join(separator,words)+" ".repeat(tail);
    }
}

code.kotlin:
class Solution {
    fun reorderSpaces(text:String):String{
        val spaces=text.count{
            it==' '
        };
        val words=text.trim().split(Regex(" +"));
        val gap=if(words.size==1)0 else spaces/(words.size-1);
        val tail=spaces-gap*(words.size-1);
        return words.joinToString(" ".repeat(gap))+" ".repeat(tail)
    }
}

code.cpp:
class Solution {
    public: string reorderSpaces(string text){
        int spaces=count(text.begin(),text.end(),' ');
        stringstream stream(text);
        vector<string> words;
        string word;
        while(stream>>word)words.push_back(word);
        int gap=words.size()==1?0:spaces/(words.size()-1),tail=spaces-gap*(words.size()-1);
        string answer;
        for(int i=0;i<(int)words.size();++i){
            if(i)answer+=string(gap,' ');
            answer+=words[i];
        }
        answer+=string(tail,' ');
        return answer;
    }
};
